#!/bin/sh
# Airvana Airave 2.5 OTASP startup patch installer, version 1.0.1.
# Only OneXApplication SHA256:
# 8a894315f36def0791e266e966fbd1726bd97c797831dd0db932b516a27b5030
# Run as root: sh /tmp/airvana-otasp.sh install
# The payload is embedded; no downloader, compiler, Python, or base64 required.
# disable stops future application; restore also removes current RAM patches.
# uninstall removes the hook and restores current RAM patches when supported.
#
set -u
umask 077
PATCHDIR=/conf_files/otasp
SCRIPT=$PATCHDIR/airvana-otasp.sh
HELPER=$PATCHDIR/patch-helper
BOOT=/etc/sysconfig/modules/airvana-otasp.modules
LEGACYBOOT=/etc/init.d/rcS
LOCK=/tmp/airvana-otasp.lock
LOG=/tmp/airvana-otasp.log
STATE=/tmp/airvana-otasp.state
VERSION=1.0.1

fail() { echo "ERROR: $*" >&2; exit 1; }
need_root() { [ "$(id -u)" = 0 ] || fail 'Run this script as root (su first).'; }
log() {
    # Keep frequent operational logs in RAM rather than wearing flash.
    if [ -f "$LOG" ] && [ "$(wc -c < "$LOG")" -gt 32768 ]; then mv -f "$LOG" "$LOG.old"; fi
    echo "$(date) $*" >> "$LOG"
}
alive_watcher() {
    [ -f "$LOCK/pid" ] || return 1
    wpid=$(cat "$LOCK/pid")
    case "$wpid" in ''|*[!0-9]*) return 1;; esac
    kill -0 "$wpid" 2>/dev/null && grep -q 'airvana-otasp.sh' "/proc/$wpid/cmdline" 2>/dev/null
}
stop_watcher() {
    if alive_watcher; then
        kill "$wpid" || return 1
        n=0
        while alive_watcher && [ "$n" -lt 20 ]; do sleep 1; n=$((n+1)); done
        alive_watcher && { echo 'Watcher still busy; wait and retry.' >&2; return 1; }
    fi
    rm -f "$LOCK/pid"
    rmdir "$LOCK" 2>/dev/null || :
}
start_watcher() {
    [ -x "$HELPER" ] && [ -f "$SCRIPT" ] || fail 'Install first.'
    [ ! -e "$PATCHDIR/disabled" ] || fail 'Disabled; run enable first.'
    if alive_watcher; then echo "Watcher already running: $wpid"; return; fi
    rm -f "$LOCK/pid"
    rmdir "$LOCK" 2>/dev/null || :
    ( trap '' HUP; exec /bin/sh "$SCRIPT" watch ) </dev/null >/dev/null 2>&1 &
    sleep 1
    alive_watcher || fail "Watcher failed to start; inspect $LOG"
    echo "Watcher started: $wpid"
}
watch() {
    need_root
    [ -x "$HELPER" ] || exit 1
    mkdir "$LOCK" 2>/dev/null || exit 0
    echo $$ > "$LOCK/pid"
    trap '' HUP
    trap 'exit 0' TERM INT
    trap 'rm -f "$LOCK/pid"; rmdir "$LOCK" 2>/dev/null || :' 0
    log "Watcher $VERSION started, PID $$"
    last_key=''
    while :; do
        [ ! -e "$PATCHDIR/disabled" ] || exit 0
        pids=$(pidof OneXApplication 2>/dev/null || :)
        set -- $pids
        if [ "$#" = 1 ]; then
            target_pid=$1
            started=$(awk '{print $22}' "/proc/$target_pid/stat" 2>/dev/null || :)
            key=$target_pid:$started
            if [ -n "$started" ] && [ "$key" != "$last_key" ]; then
                log "Checking new OneXApplication instance $key"
                if "$HELPER" apply "$target_pid" >> "$LOG" 2>&1; then
                    echo "patched $key" > "$STATE"
                    log "OTASP patch active on $key"
                else
                    echo "failed $key" > "$STATE"
                    log "Patch refused/failed on $key; inspect log. No repeated attach to this instance."
                fi
                last_key=$key
            fi
        elif [ "$#" = 0 ]; then
            last_key=''
        fi
        sleep 5
    done
}
extract_helper() {
    # Old BusyBox has neither base64 nor uudecode. printf is a shell builtin.
    # Each line encodes 64 bytes with portable octal escapes.
    sed -n '/^__OTASP_PAYLOAD_V1__$/,$p' "$0" | (
        IFS= read -r marker
        while IFS= read -r octets; do printf '%b' "$octets" || exit 1; done
    ) > "$1"
}
install() {
    need_root
    [ -d /etc/sysconfig/modules ] && grep -Fq 'for file in /etc/sysconfig/modules/*.modules' /etc/rc.sysinit || fail 'Unsupported startup module layout.'
    if [ -e "$BOOT" ] && ! grep -q '^# AIRVANA OTASP STARTUP MODULE V1$' "$BOOT"; then fail 'Startup hook path already belongs to another file.'; fi
    [ ! -e /etc_rw/sysconfig/modules/airvana-otasp.modules ] || fail 'Stock firmware now owns this hook name; inspect before installing.'
    [ -x /usr/bin/gdbserver ] || fail 'Firmware gdbserver is missing.'
    [ -d /conf_files ] && [ -w /conf_files ] || fail 'Persistent storage is unavailable.'
    mkdir -p "$PATCHDIR" || fail 'Cannot create persistent patch directory.'
    chmod 700 "$PATCHDIR" || fail 'Cannot protect patch directory.'
    [ ! -e "$PATCHDIR/disabled" ] || fail 'Installation is disabled; use enable or remove disabled flag intentionally.'
    tmphelper=$PATCHDIR/patch-helper.new
    extract_helper "$tmphelper" || fail 'Payload extraction failed.'
    chmod 700 "$tmphelper" || fail 'Cannot make helper executable.'
    "$tmphelper" --selftest || { rm -f "$tmphelper"; fail 'Helper cannot run on this device.'; }
    "$tmphelper" --verify /usr/bin/OneXApplication || { rm -f "$tmphelper"; fail 'Unsupported firmware; startup hook was not changed.'; }
    stop_watcher || fail 'Cannot stop previous watcher.'
    mv -f "$tmphelper" "$HELPER" || fail 'Cannot install helper.'
    # Atomic self-copy works when re-running the installed script as well.
    cp "$0" "$SCRIPT.new" || fail 'Cannot copy installer.'
    chmod 700 "$SCRIPT.new" || fail 'Cannot protect installer.'
    mv -f "$SCRIPT.new" "$SCRIPT" || fail 'Cannot install script.'
    # /init restores stock etc_rw files each boot, but preserves added files.
    # Install a new .modules file rather than edit a stock startup script.
    cat > "$BOOT.new" <<'OTASP_BOOT'
#!/bin/sh
# AIRVANA OTASP STARTUP MODULE V1
if [ -f /conf_files/otasp/airvana-otasp.sh ] && [ ! -e /conf_files/otasp/disabled ]; then
    /bin/sh /conf_files/otasp/airvana-otasp.sh start >/tmp/airvana-otasp-start.log 2>&1 </dev/null &
fi
OTASP_BOOT
    chmod 700 "$BOOT.new" || fail 'Cannot make startup hook executable.'
    /bin/sh -n "$BOOT.new" || fail 'Startup hook syntax check failed.'
    mv -f "$BOOT.new" "$BOOT" || fail 'Cannot activate startup hook.'
    # Migrate the earlier experimental rcS hook if it is still present.
    if grep -q '^# BEGIN AIRVANA OTASP STARTUP$' "$LEGACYBOOT"; then
        cp -p "$LEGACYBOOT" "$LEGACYBOOT.otasp-new" || fail 'Cannot stage legacy hook cleanup.'
        sed '/^# BEGIN AIRVANA OTASP STARTUP$/,/^# END AIRVANA OTASP STARTUP$/d' "$LEGACYBOOT" > "$LEGACYBOOT.otasp-new" || fail 'Cannot clean legacy hook.'
        /bin/sh -n "$LEGACYBOOT.otasp-new" || fail 'Legacy startup syntax check failed.'
        mv -f "$LEGACYBOOT.otasp-new" "$LEGACYBOOT" || fail 'Cannot activate legacy hook cleanup.'
    fi
    sync
    start_watcher
    echo 'Installed. Current and future OneXApplication instances will be patched.'
    echo "Status: sh $SCRIPT status"
}
restore_live() {
    pids=$(pidof OneXApplication 2>/dev/null || :)
    set -- $pids
    [ "$#" -le 1 ] || fail 'Multiple OneXApplication processes; refusing restore.'
    [ "$#" = 0 ] || "$HELPER" restore "$1" || fail 'RAM restore failed; files and disable flag retained.'
}
uninstall() {
    need_root
    [ -x "$HELPER" ] || fail 'Helper missing; inspect installation manually.'
    touch "$PATCHDIR/disabled" || fail 'Cannot disable.'
    stop_watcher || fail 'Cannot stop watcher.'
    restore_live
    if [ -e "$BOOT" ]; then
        grep -q '^# AIRVANA OTASP STARTUP MODULE V1$' "$BOOT" || fail 'Startup hook no longer belongs to this installer; inspect manually.'
        rm -f "$BOOT" || fail 'Cannot remove startup hook.'
    fi
    rm -f "$SCRIPT" "$HELPER" "$STATE" "$PATCHDIR/disabled" "$PATCHDIR/disabled"
    sync
    echo "Uninstalled. Startup module removed and RAM patches restored."
}
status() {
    echo "Airvana OTASP startup patch $VERSION"
    if grep -q '^# AIRVANA OTASP STARTUP MODULE V1$' "$BOOT"; then echo 'Startup hook: installed'; else echo 'Startup hook: absent'; fi
    if [ -e "$PATCHDIR/disabled" ]; then echo 'Automatic patching: disabled'; else echo 'Automatic patching: enabled'; fi
    if alive_watcher; then echo "Watcher: running ($wpid)"; else echo 'Watcher: stopped'; fi
    echo "OneXApplication PID(s): $(pidof OneXApplication 2>/dev/null || :)"
    [ ! -f "$STATE" ] || { echo -n 'Last result: '; cat "$STATE"; }
    [ ! -f "$LOG" ] || tail -n 12 "$LOG"
}
action='install'
[ "$#" = 0 ] || action=$1
case "$action" in
    install) install;;
    watch) watch;;
    start) need_root; start_watcher;;
    stop) need_root; stop_watcher;;
    disable) need_root; touch "$PATCHDIR/disabled" || fail 'Install first.'; stop_watcher || fail 'Cannot stop watcher.'; echo 'Automatic patching disabled; existing RAM patches remain until restore/restart.';;
    enable) need_root; [ -x "$HELPER" ] || fail 'Install first.'; rm -f "$PATCHDIR/disabled"; start_watcher;;
    restore) need_root; touch "$PATCHDIR/disabled" || fail 'Install first.'; stop_watcher || fail 'Cannot stop watcher.'; restore_live; rm -f "$STATE";;
    check) need_root; pids=$(pidof OneXApplication 2>/dev/null || :); set -- $pids; [ "$#" = 1 ] || fail 'Expected one OneXApplication process.'; "$HELPER" check "$1"; exit $?;;
    status) status;;
    uninstall) uninstall;;
    *) fail 'Usage: sh airvana-otasp.sh install|status|check|enable|disable|restore|uninstall';;
esac
exit 0
__OTASP_PAYLOAD_V1__
